require_once __DIR__ . '/includes/club_event_registration.php';
require_once __DIR__ . '/includes/club_event_shop.php';
require_once __DIR__ . '/includes/club_event_export.php';
if (!isset($_SESSION['trener_id']) || !roleAtLeast('admin')) { header('Location: login.php'); exit; }
function eventAdminH(mixed $value): string { return htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); }
$errors=[];
if ($_SERVER['REQUEST_METHOD']==='POST') {
    if (!csrf_verify((string)($_POST['csrf_token']??''))) $errors[]='Formulář vypršel. Obnovte stránku.';
    else {
        try {
            $action=(string)($_POST['action']??'');$eventId=(int)($_POST['event_id']??0);$actor=(int)$_SESSION['trener_id'];
            if ($action==='create') {
                $result=clubEventCreateDraft($pdo,$actor,$_POST);$eventId=$result['id'];$_SESSION['flash_event_success']='Pracovní klubová akce byla založena.';
            } elseif ($action==='update_event') {
                $result=clubEventUpdateDraft($pdo,$eventId,$actor,$_POST,(string)($_POST['note']??''),($_POST['confirm_change']??'')==='1');$_SESSION['flash_event_success']=$result['changed']?'Základní údaje akce byly upraveny.':'Údaje akce se nezměnily.';
            } elseif ($action==='add_session') {
                clubEventAddSession($pdo,$eventId,$actor,(string)($_POST['starts_at']??''),(string)($_POST['ends_at']??''),(string)($_POST['location']??''),($_POST['capacity_override']??'')===''?null:(int)$_POST['capacity_override']);$_SESSION['flash_event_success']='Termín byl přidán.';
            } elseif ($action==='update_session') {
                $result=clubEventUpdateSession($pdo,$eventId,(int)($_POST['session_id']??0),$actor,(string)($_POST['starts_at']??''),(string)($_POST['ends_at']??''),(string)($_POST['location']??''),($_POST['capacity_override']??'')===''?null:(int)$_POST['capacity_override'],(string)($_POST['note']??''),($_POST['confirm_change']??'')==='1');$_SESSION['flash_event_success']=$result['changed']?'Termín byl upraven.':'Termín se nezměnil.';
            } elseif ($action==='cancel_session') {
                $result=clubEventCancelSession($pdo,$eventId,(int)($_POST['session_id']??0),$actor,(string)($_POST['note']??''),($_POST['confirm_change']??'')==='1');$_SESSION['flash_event_success']=$result['changed']?'Termín byl zrušen.':'Termín už byl zrušen.';
            } elseif ($action==='link_product') {
                $result=clubEventLinkProduct($pdo,$eventId,(int)($_POST['product_id']??0),$actor,(string)($_POST['note']??''));$_SESSION['flash_event_success']=$result['created']?'Produkt byl propojen s akcí.':'Produkt už byl s akcí propojen.';
            } elseif ($action==='unlink_product') {
                clubEventUnlinkProduct($pdo,$eventId,(int)($_POST['link_id']??0),$actor,(string)($_POST['note']??''));$_SESSION['flash_event_success']='Produkt byl od akce odpojen.';
            } elseif ($action==='configure_terms') {
                $result=clubEventConfigureRegistrationTerms($pdo,$eventId,$actor,(string)($_POST['terms_version']??''),(string)($_POST['consent_text_plain']??''),(string)($_POST['cancellation_policy_plain']??''),(string)($_POST['cancellation_deadline_at']??''),($_POST['confirm_terms']??'')==='1');$_SESSION['flash_event_success']=$result['changed']?'Souhlas a storno podmínky byly uloženy.':'Podmínky se nezměnily.';
            } elseif ($action==='set_roster_targets') {
                $result=clubEventRosterReplaceTargets($pdo,$eventId,(array)($_POST['team_ids']??[]),$actor,(string)($_POST['note']??''),($_POST['confirm_targets']??'')==='1');$_SESSION['flash_event_success']=$result['changed']?'Cílové soupisky byly uloženy.':'Cílení se nezměnilo.';
            } elseif ($action==='open_free') {
                $result=clubEventOpenFreeRegistration($pdo,$eventId,$actor,(string)($_POST['note']??''),($_POST['confirm_open']??'')==='1');$_SESSION['flash_event_success']=$result['changed']?'Bezplatný kroužek byl otevřen pro přihlášení.':'Kroužek už je otevřený.';
            } elseif ($action==='open_paid') {
                $result=clubEventOpenPaidRegistration($pdo,$eventId,$actor,(string)($_POST['note']??''),($_POST['confirm_open']??'')==='1');$_SESSION['flash_event_success']=$result['changed']?'Placená událost byla otevřena pro přihlášení.':'Událost už je otevřená.';
            } elseif ($action==='close_registration') {
                $result=clubEventCloseRegistration($pdo,$eventId,$actor,(string)($_POST['note']??''));$_SESSION['flash_event_success']=$result['changed']?'Přihlašování bylo uzavřeno.':'Přihlašování už bylo uzavřeno.';
            } elseif ($action==='reopen_draft') {
                $result=clubEventReopenDraft($pdo,$eventId,$actor,(string)($_POST['note']??''),($_POST['confirm_change']??'')==='1');$_SESSION['flash_event_success']=$result['changed']?'Akce byla vrácena do pracovního stavu.':'Akce už je pracovní.';
            } elseif ($action==='archive_event') {
                $result=clubEventArchive($pdo,$eventId,$actor,(string)($_POST['note']??''),($_POST['confirm_change']??'')==='1');$_SESSION['flash_event_success']=$result['changed']?'Akce byla archivována.':'Akce už je archivována.';
            } elseif ($action==='admin_cancel_registration') {
                $result=clubEventAdminCancelRegistration($pdo,(int)($_POST['registration_id']??0),$actor,(string)($_POST['note']??''),($_POST['confirm_admin_cancel']??'')==='1');$_SESSION['flash_event_success']=$result['changed']?'Přihláška byla administrativně zrušena'.($result['promoted_registration_id']?' a první způsobilý čekající byl potvrzen.':'.'):'Přihláška už byla zrušena.';
            } else throw new InvalidArgumentException('Neplatná akce.');
            header('Location: eshop_events_admin.php?event_id='.$eventId,true,303);exit;
        } catch (PDOException $exception) { error_log('eshop_events_admin.php: '.$exception->getMessage());$errors[]='Databázová operace selhala bez částečného zápisu.'; }
        catch (InvalidArgumentException|ClubEventException|ClubEventRegistrationException|ClubEventRosterTargetException $exception) { $errors[]=$exception->getMessage(); }
    }
}
$success=(string)($_SESSION['flash_event_success']??'');unset($_SESSION['flash_event_success']);
$events=clubEventList($pdo);$eventId=max(0,(int)($_GET['event_id']??0));if ($eventId===0&&$events!==[])$eventId=(int)$events[0]['id'];$detail=$eventId?clubEventDetail($pdo,$eventId):null;
$rosterTargets=$detail?clubEventRosterTargets($pdo,$eventId):[];$rosterTargetIds=array_map('intval',array_column($rosterTargets,'team_id'));$availableTeams=clubEventRosterAvailableTeams($pdo);
$registrationCount=0;$waitlistCount=0;$effectiveCapacity=0;$registrationRows=[];if($detail){$capacityStatement=$pdo->prepare("SELECT status,COUNT(*) AS total FROM club_event_registrations WHERE event_id=? AND status IN ('confirmed','waitlisted') GROUP BY status");$capacityStatement->execute([$eventId]);foreach($capacityStatement->fetchAll(PDO::FETCH_ASSOC)as$countRow){if($countRow['status']==='confirmed')$registrationCount=(int)$countRow['total'];else$waitlistCount=(int)$countRow['total'];}$effectiveCapacity=clubEventEffectiveCapacity($pdo,$eventId,(int)$detail['event']['capacity']);$registrationStatement=$pdo->prepare("SELECT r.*,s.jmeno,s.prijmeni,vu.email FROM club_event_registrations r JOIN sportovci s ON s.id=r.sportovec_id JOIN verejni_uzivatele vu ON vu.id=r.account_id WHERE r.event_id=? ORDER BY CASE r.status WHEN 'confirmed' THEN 0 WHEN 'waitlisted' THEN 1 ELSE 2 END,r.waitlisted_at,r.id");$registrationStatement->execute([$eventId]);$registrationRows=$registrationStatement->fetchAll(PDO::FETCH_ASSOC);}
$products=$pdo->query("SELECT p.id,p.name,p.offer_type,p.catalog_status FROM shop_products p WHERE p.offer_type IN ('club_event','camp') AND NOT EXISTS (SELECT 1 FROM shop_product_event_links l WHERE l.product_id=p.id) ORDER BY p.name,p.id")->fetchAll(PDO::FETCH_ASSOC);
?>
